def find_order(base, modulus):
    k = 1
    while True:
        if pow(base, k, modulus) == 1:
            return k
        k += 1

# Order modulo 625
modulus_625 = 625
order_625 = find_order(3, modulus_625)
print(f"Order of 3 modulo 625: {order_625}")

def power_mod(base, exponent, modulus):
    return pow(base, exponent, modulus)

print(f"3^1 mod 10000: {power_mod(3, 1, 10000)}")
print(f"3^500 mod 10000: {power_mod(3, 500, 10000)}")
